    jobend: { t: 'How long you will do this job', b: 'Enter how many months from today the job ends. Leave it blank if there is no end date. This is useful for a temporary or seasonal job.' },
    jobstart: { t: 'When the job starts', b: 'Months from today. 0 means you already have the job.' },
    grosspay: { t: 'Gross pay', b: 'Your pay for the year before any taxes are taken out.' }
